    rpr=run.find(q("rPr"))
    if rpr is None: rpr=ET.Element(q("rPr")); run.insert(0,rpr)
    col=rpr.find(q("color"))
    if col is None: col=ET.SubElement(rpr,q("color"))
    col.set(q("val"), val)
for cell in document.findall(".//"+q("tc")):
    txt="".join(t.text or "" for t in cell.findall(".//"+q("t"))).strip()
    m=re.search(r"[A-Za-z]", txt)
    if m:
        val="FF0000" if txt[m.start()].lower() in "aeiou" else "0000FF"
        for run in cell.findall(".//"+q("r")):
            if "".join(t.text or "" for t in run.findall(".//"+q("t"))).strip():
                set_color(run,val)
